export type MessageKey = keyof typeof I18N.en;
export function normalizeLanguage(value: unknown): Language { return value === 'tr' ? 'tr' : 'en'; }
export function t(key: MessageKey, language: Language = 'en', values?: Record<string, string | number>): string {
  let value: string = I18N[language][key] || I18N.en[key];
  for (const [name, replacement] of Object.entries(values || {})) value = value.replaceAll(`{${name}}`, String(replacement));
  return value;
}






